// Loading-screen map warp (portal_map_warp.h, generated by tools/map/make_map.py): each
// landmark lands on its painted place, and the whole world stays on or near the painting.
#include "../src/portal_map_warp.h"
#include <cstdio>

static int failures = 0;
#define CHECK(x) do { if (!(x)) { std::printf("FAIL %s:%d %s\n", __FILE__, __LINE__, #x); ++failures; } } while (0)

int main() {
    struct Landmark { const char* name; double x, z, u, v; };
    // World positions (portal_locations.h) and painted pixels on the 1254 px map.
    const Landmark landmarks[] = {
        {"Springlands Spire", 3507.97, 1957.16, 480, 1000}, {"Albaneve Spire", 7451.19, 4932.59, 928, 575},
        {"Kindlewastes Spire", 8402.62, 2468.57, 1028, 935}, {"Veilwater Spire", 4737.97, 5531.16, 578, 435},
    };
    for (const auto& l : landmarks) {
        double u, v;
        portal::mapwarp::ToMap(l.x, l.z, u, v);
        CHECK(std::fabs(u * 1254 - l.u) < 0.5 && std::fabs(v * 1254 - l.v) < 0.5);
    }
    // The playable world (about 500..9700 m each way) maps onto the painting, give or take its frame.
    for (double x = 500; x <= 9700; x += 400)
        for (double z = 500; z <= 9700; z += 400) {
            double u, v;
            portal::mapwarp::ToMap(x, z, u, v);
            CHECK(u > -0.15 && u < 1.15 && v > -0.25 && v < 1.15);
        }
    // North is up and east is right everywhere in the middle of the world.
    for (double x = 2500; x <= 8500; x += 1000)
        for (double z = 1500; z <= 7500; z += 1000) {
            double u0, v0, ue, ve, un, vn;
            portal::mapwarp::ToMap(x, z, u0, v0);
            portal::mapwarp::ToMap(x + 100, z, ue, ve);
            portal::mapwarp::ToMap(x, z + 100, un, vn);
            CHECK(ue > u0 && vn < v0);
        }
    if (failures) { std::printf("%d failure(s)\n", failures); return 1; }
    std::printf("loading map warp: all checks passed\n");
    return 0;
}
